if(location.href!=="http://127.0.0.1:5173/upload") throw new Error('论文地址已变化');
const expected={'论文正文':['移除 2017 YHn LaHn-彭枫.pdf'],'补充材料':['移除 2017 YHn LaHn-彭枫 Supplementary.pdf']};const selected={};for(const [role,names] of Object.entries(expected)){const region=document.querySelector('[role="region"][aria-label="'+role+'"]');const found=[...region.querySelectorAll('button[aria-label^="移除 "]')].map(b=>b.getAttribute('aria-label'));if(JSON.stringify(found)!==JSON.stringify(names))throw new Error('真实上传清单不符:'+role);selected[role]=found;}const buttons=[...document.querySelectorAll('button')].filter(b=>b.textContent.trim()==='开始上传并解析');if(buttons.length!==1||buttons[0].disabled)throw new Error('上传按钮不可用');buttons[0].click();return {url:location.href,action:'正常组件开始上传并解析',selected,time:new Date().toISOString()};